Phase read_Phase(const Value& value, const std::string& path)
{
    if (value.kind() == Value::Kind::string) {
        const auto& member = value.as_string();
        if (member == "simulation") return Phase::simulation;
        if (member == "planning") return Phase::planning;
    }
    fail(path, "expected a member of Phase");
}

Value write_Phase(const Phase& value)
{
    switch (value) {
    case Phase::simulation: return Value("simulation");
    case Phase::planning: return Value("planning");
    }
    throw std::invalid_argument("invalid Phase value");
}

