BalancePreset read_BalancePreset(const Value& value, const std::string& path)
{
    if (value.kind() == Value::Kind::string) {
        const auto& member = value.as_string();
        if (member == "free") return BalancePreset::free;
        if (member == "cheap") return BalancePreset::cheap;
        if (member == "fair") return BalancePreset::fair;
        if (member == "expensive") return BalancePreset::expensive;
        if (member == "calculated") return BalancePreset::calculated;
    }
    fail(path, "expected a member of BalancePreset");
}

Value write_BalancePreset(const BalancePreset& value)
{
    switch (value) {
    case BalancePreset::free: return Value("free");
    case BalancePreset::cheap: return Value("cheap");
    case BalancePreset::fair: return Value("fair");
    case BalancePreset::expensive: return Value("expensive");
    case BalancePreset::calculated: return Value("calculated");
    }
    throw std::invalid_argument("invalid BalancePreset value");
}

BalanceValue read_BalanceValue(const Value& value, const std::string& path)
{
    std::optional<BalanceValue> result;
    std::size_t matches = 0;
    try {
        auto candidate = read_number(value, path);
        if (++matches == 1) result.emplace(std::in_place_index<0>, std::move(candidate));
    } catch (const ImportError&) {}
    try {
        auto candidate = read_BalancePreset(value, path);
        if (++matches == 1) result.emplace(std::in_place_index<1>, std::move(candidate));
    } catch (const ImportError&) {}
    if (matches != 1) fail(path, "expected exactly one variant of BalanceValue; matched " + std::to_string(matches));
    return std::move(*result);
}

Value write_BalanceValue(const BalanceValue& value)
{
    switch (value.index()) {
    case 0: return write_number(std::get<0>(value));
    case 1: return write_BalancePreset(std::get<1>(value));
    }
    throw std::invalid_argument("invalid BalanceValue variant");
}

