Quality read_Quality(const Value& value, const std::string& path)
{
    if (value.kind() == Value::Kind::string) {
        const auto& member = value.as_string();
        if (member == "bronze") return Quality::bronze;
        if (member == "silver") return Quality::silver;
        if (member == "gold") return Quality::gold;
        if (member == "diamond") return Quality::diamond;
    }
    fail(path, "expected a member of Quality");
}

Value write_Quality(const Quality& value)
{
    switch (value) {
    case Quality::bronze: return Value("bronze");
    case Quality::silver: return Value("silver");
    case Quality::gold: return Value("gold");
    case Quality::diamond: return Value("diamond");
    }
    throw std::invalid_argument("invalid Quality value");
}

