PendingLifeMapKind read_PendingLifeMapKind(const Value& value, const std::string& path)
{
    if (value.kind() == Value::Kind::string) {
        const auto& member = value.as_string();
        if (member == "nodeResolution") return PendingLifeMapKind::nodeResolution;
        if (member == "shopDelve") return PendingLifeMapKind::shopDelve;
        if (member == "campaignEncounter") return PendingLifeMapKind::campaignEncounter;
    }
    fail(path, "expected a member of PendingLifeMapKind");
}

Value write_PendingLifeMapKind(const PendingLifeMapKind& value)
{
    switch (value) {
    case PendingLifeMapKind::nodeResolution: return Value("nodeResolution");
    case PendingLifeMapKind::shopDelve: return Value("shopDelve");
    case PendingLifeMapKind::campaignEncounter: return Value("campaignEncounter");
    }
    throw std::invalid_argument("invalid PendingLifeMapKind value");
}

